import{_ as o,o as r,c as n,a2 as p}from"./chunks/framework.DnrXFDHb.js";const l=JSON.parse('{"title":"县域智算中心：真普惠还是新圈地","description":"","frontmatter":{"title":"县域智算中心：真普惠还是新圈地","updated":"2026-09-02T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"算电协同/县域智算中心_真普惠还是新圈地.md","filePath":"算电协同/县域智算中心_真普惠还是新圈地.md","lastUpdated":null}'),a={name:"算电协同/县域智算中心_真普惠还是新圈地.md"};function s(e,t,u,q,g,h){return r(),n("div",null,[...t[0]||(t[0]=[p('<h1 id="县域智算中心-是真普惠-还是新圈地-城投转型做token工厂的隐忧-该怎么看-算力建设热-理性拆解一下。" tabindex="-1">县域智算中心：是真普惠，还是新圈地？城投转型做Token工厂的隐忧，该怎么看？算力建设热，理性拆解一下。 <a class="header-anchor" href="#县域智算中心-是真普惠-还是新圈地-城投转型做token工厂的隐忧-该怎么看-算力建设热-理性拆解一下。" aria-label="Permalink to &quot;县域智算中心：是真普惠，还是新圈地？城投转型做Token工厂的隐忧，该怎么看？算力建设热，理性拆解一下。&quot;">​</a></h1><p><strong>前言</strong>：我干了20年地产，管过基金、做过经营性物业的募投管退，最近几年又扎进电力交易和HVDC供电架构。现在开这个号，就是想用&quot;资产+电力&quot;的双重视角，把算电协同这件事讲清楚。本文由AI帮我整理资料和初稿，但每一个判断——比如为什么我说&quot;县域智算中心的普惠叙事里，藏着地产式圈地的老剧本&quot;——都是我自己的体感。也欢迎您在评论区拍砖、讨论、切磋。</p><hr><h2 id="一台gb200机架的功率-够一个中型超市用一年。但全国智算中心的平均利用率-只有30-。" tabindex="-1">一台GB200机架的功率，够一个中型超市用一年。但全国智算中心的平均利用率，只有30%。 <a class="header-anchor" href="#一台gb200机架的功率-够一个中型超市用一年。但全国智算中心的平均利用率-只有30-。" aria-label="Permalink to &quot;一台GB200机架的功率，够一个中型超市用一年。但全国智算中心的平均利用率，只有30%。&quot;">​</a></h2><p>换句话说，你花几千万买的芯片，有七成时间在空转——电费照交，折旧照提，但产出几乎为零。这让我想起当年地产行业的一个老词：<strong>鬼城</strong>。</p><hr><h2 id="算力建设热-闻着越来越像地产味" tabindex="-1">算力建设热，闻着越来越像地产味 <a class="header-anchor" href="#算力建设热-闻着越来越像地产味" aria-label="Permalink to &quot;算力建设热，闻着越来越像地产味&quot;">​</a></h2><p>2025年上半年，全国冒出393个智算中心相关项目。截至2024年底，已投运的接近150个，在建和规划的还有近400个。</p><p>这个节奏，我熟。</p><p>十年前各地建新区、建综合体，也是这个打法——<strong>先把地圈下来，把楼盖起来，再琢磨谁来租、谁来买</strong>。那时候的逻辑是&quot;筑巢引凤&quot;，现在的说法是&quot;普惠算力&quot;。名字变了，剧本没变。</p><p>更熟悉的是&quot;算力券&quot;这套玩法。湖北省级财政2025年发5000万算力券，重庆每年安排5000万，北京更狠，每年10个亿。企业租用智算中心算力，政府补贴10%到20%。</p><p>这让我想起当年各地为了去库存，出台的购房补贴、契税减免、人才安家费。<strong>补贴本身没错，但如果补贴的是一座没人住的楼，那就是在延缓出清、放大泡沫。</strong></p><p>算力不是地产，但建设算力的人，用的还是地产那套肌肉记忆。</p><hr><h2 id="普惠-是面子-圈地-才是里子" tabindex="-1">&quot;普惠&quot;是面子，&quot;圈地&quot;才是里子？ <a class="header-anchor" href="#普惠-是面子-圈地-才是里子" aria-label="Permalink to &quot;&quot;普惠&quot;是面子，&quot;圈地&quot;才是里子？&quot;">​</a></h2><p>县域智算中心的叙事很动人：让偏远地区也能用上AI，降低中小企业算力门槛，缩小数字鸿沟。</p><p>但数据不会骗人。</p><p>浪潮人工智能研究院测算，<strong>全国智算中心平均算力使用率约30%</strong>。部分三四线城市中小规模智算中心，整体利用率不足三成。更扎心的是，<strong>部分国产芯片的闲置率高达70%到80%</strong>。</p><p>《科技日报》报道过一个典型案例：西部某城千卡规模智算中心，上架率不足50%，已上架服务器实际利用率不到30%，<strong>年运营成本超过3000万元</strong>。</p><p>千卡级集群是什么概念？大概相当于一个中型制造企业的全年用电负荷。但这座智算中心的产出，连电费都盖不住。</p><p>一位业内人士算过账：一个千卡级集群年运营成本（电费、人工、折旧）约5000万元，如果利用率只有30%，实际营收可能不到2300万元。<strong>投资回报周期从预期的3到5年，直接拖到8到10年。</strong></p><p>这跟我当年看过的县域商业地产项目，几乎是一个模子刻出来的——<strong>名义上普惠市民，实际上成了地方债的包袱。</strong></p><hr><h2 id="城投转型卖token-老酒装新瓶" tabindex="-1">城投转型卖Token：老酒装新瓶？ <a class="header-anchor" href="#城投转型卖token-老酒装新瓶" aria-label="Permalink to &quot;城投转型卖Token：老酒装新瓶？&quot;">​</a></h2><p>最近有个新词火了：Token工厂。</p><p>嘉兴城投集团主导运营&quot;长三角（嘉兴）Token运营中心&quot;，温州数据集团搞&quot;东南Token运营中心&quot;，济南城投建&quot;泉惠算·济南词元工厂&quot;，北京、广州也在跟进。甚至无锡高新区科创产业发展集团已经发行科技创新公司债，<strong>募集资金重点投向Token工厂项目</strong>。</p><p>Token是什么？简单说，就是大模型处理文本时的最小单位。以前城投修路、盖楼、铺管网，现在开始&quot;卖Token&quot;了。</p><p>官方定位很清晰：Token运营中心自己不生产算力，而是把分散的算力、各种AI大模型整合起来，以标准化服务提供给企业，相当于<strong>区域性的AI算力&quot;批发市场&quot;或&quot;总代理&quot;</strong>。</p><p>听起来很美好。但作为一个跟城投打了二十年交道的人，我得泼一盆冷水。</p><p><strong>城投的核心能力是什么？是融资、是基建、是拿地和报批。但算力中心的核心能力是什么？是运营、是调度、是找客户、是懂AI训练推理的差异化需求。</strong></p><p>这两个能力谱系，基本不重叠。</p><p>就像当年很多城投公司建完商场，发现自己根本不会招商运营，最后只能低价甩给专业运营商。现在建完智算中心，就能突然学会卖Token了？</p><p>盘古智库高级研究员江瀚说，这本质上是&quot;城市基础设施运营逻辑的平移&quot;。我理解这个逻辑，但<strong>平移的是&quot;基建思维&quot;，不是&quot;运营思维&quot;</strong>。修路可以平移，卖算力没法平移。</p><p>更让我警惕的是，Token正在进入地方国企真实的投资和融资体系。当Token从一个AI计量单位，变成发债募资的底层资产，<strong>这个泡沫的复杂度和隐蔽性，比当年的土地财政只高不低。</strong></p><hr><h2 id="真正的矛盾不是-有没有电-而是-有没有需求" tabindex="-1">真正的矛盾不是&quot;有没有电&quot;，而是&quot;有没有需求&quot; <a class="header-anchor" href="#真正的矛盾不是-有没有电-而是-有没有需求" aria-label="Permalink to &quot;真正的矛盾不是&quot;有没有电&quot;，而是&quot;有没有需求&quot;&quot;">​</a></h2><p>国家信息中心单志广主任有个判断，我觉得一针见血：<strong>&quot;现在全国多地在抢建算力中心，主要的推手不是应用需求，而是建设厂商的供给需求。&quot;</strong></p><p>换句话说，是卖铲子的人在喊&quot;金矿很大&quot;，至于有没有金子，另说。</p><p>央行调查统计司原司长盛松成最近也发了一篇重磅文章，标题很直接：<strong>《地方须摒弃AI投资对房地产的&quot;替代&quot;幻觉》</strong>。他指出，部分项目先建设、后寻找客户，收入预测缺少已签订合同支撑；不同地区和运营主体重复布局，而跨区域调度、计量和交易机制尚不完善；<strong>部分项目需要持续财政补贴才能维持运营</strong>。</p><p>这才是问题的核心。</p><p><strong>算力产业当前不是&quot;总量过剩&quot;，而是&quot;结构错配&quot;。</strong> 一边是中小企业苦苦寻求高端算力却&quot;一卡难求&quot;，另一边是大量已建成的智算中心实际利用率低于40%。高端算力饥渴难耐，低端算力吃不饱——这种割裂，跟当年商业地产&quot;核心地段一铺难求、郊区 mall 门可罗雀&quot;的剧本，何其相似。</p><p>还有一个更深层的问题：<strong>国产芯片的生态瓶颈</strong>。不少智算中心采购了国产GPU，但因为软件栈不完善、兼容性差，企业根本用不起来。硬件摆在那儿，算力却释放不出来。这就好比盖了一座商场，电梯品牌跟所有货柜都不兼容，商户进不来。</p><hr><h2 id="对资产层面意味着什么" tabindex="-1">对资产层面意味着什么？ <a class="header-anchor" href="#对资产层面意味着什么" aria-label="Permalink to &quot;对资产层面意味着什么？&quot;">​</a></h2><p>我反复说一句话：<strong>智算中心本质上就是新型基础设施资产。</strong></p><p>既然是资产，就得用资产的逻辑来看——选址看土地和电力资源，运营看现金流和出租率，退出看资本化率和资产溢价。这个框架下，当前大量县域智算中心的问题就暴露得很清楚了。</p><p><strong>第一，&quot;募投管退&quot;的闭环没跑通。</strong> 现在各地热衷的是&quot;投&quot;——立项、拿地、建楼、买卡。但&quot;管&quot;（运营效率、客户获取、算力调度）和&quot;退&quot;（资产变现、REITs退出、股权交易）基本没想好。当年地产基金最惨的项目，就是只有投、没有管和退的项目。</p><p><strong>第二，电力成本正在吃掉资产模型。</strong> 利用率30%意味着什么？意味着你交的电费里，70%是在为空气买单。我以前算过，智算中心TCO里电力相关成本（含供电设施折旧）已经占到40%以上。如果利用率上不去，这笔账会迅速把项目拖入亏损深渊。</p><p><strong>第三，算力本身不是新地段，电力才是。</strong> 我过去说&quot;电力正在变成下一代基础设施的地段&quot;，这个判断在县域智算中心身上得到了反向验证——<strong>没有便宜且稳定的电，算力建起来就是负资产</strong>。很多县城建智算中心，电力资源并不充裕，PUE也做不到1.2以下，先天就输在起跑线上。</p><hr><h2 id="所以-该怎么看" tabindex="-1">所以，该怎么看？ <a class="header-anchor" href="#所以-该怎么看" aria-label="Permalink to &quot;所以，该怎么看？&quot;">​</a></h2><p>我不否定算力需求的真实存在。AI大模型的训练和推理，确实需要海量算力支撑。但这个需求是<strong>分层、分区域、分场景</strong>的，不是每个县都需要一个智算中心。</p><p><strong>理性看待算力建设热，关键是区分三种逻辑：</strong></p><p><strong>第一种是需求驱动型</strong>——比如靠近大型模型厂商、有明确客户订单、电力资源富集的项目。这种项目值得投，但要算清TCO和利用率。</p><p><strong>第二种是产业配套型</strong>——比如围绕特定制造业集群、有垂直场景（自动驾驶、生物医药）支撑的项目。这种项目要看产业协同深度，不能只看算力规模。</p><p><strong>第三种是基建拉动型</strong>——就是为了投资、为了政绩、为了替代下滑的土地财政而上马的项目。这种项目，我劝你躲远点。</p><p>当年地产行业有一句话：<strong>&quot;当卖菜的大妈都开始讨论买房的时候，就是该警惕的时候。&quot;</strong> 现在，当每个县城都开始规划智算中心的时候，我觉得同理。</p><hr><p><strong>数据来源：</strong></p><p>[1] 浪潮人工智能研究院（2025）｜全国智算中心平均算力使用率约30%</p><p>[2] 《科技日报》（2025.07）｜西部某城千卡智算中心利用率及运营成本案例</p><p>[3] 中国新闻周刊/财联社（2026.08）｜嘉兴、温州、济南等地城投Token运营中心动态</p><p>[4] 盛松成/财新（2026.08）｜《地方须摒弃AI投资对房地产的&quot;替代&quot;幻觉》核心判断</p><p>[5] 国家信息中心单志广（2024）｜算力建设主要推手是供给需求而非应用需求</p><hr><p>⚠️ <strong>风险提示</strong>：算力利用率持续低迷风险｜地方财政补贴退坡风险。本文仅作产业研究，不构成任何投资建议。</p><hr><p>关注「算电协同研习社」，看懂算力与电力的下一个十年。<strong>也欢迎在评论区拍砖——你觉得县域智算中心是真需求还是新圈地？一个人捋容易钻牛角尖，一群人捋才能捋透。</strong></p>',68)])])}const d=o(a,[["render",s]]);export{l as __pageData,d as default};
